var allGOs = Resources.FindObjectsOfTypeAll<GameObject>();
foreach(var go in allGOs){
    if(go.scene.name != "Game_Garden") continue;
    if(go.name == "WaterSpout" || go.name == "SpillEffect"){
        string path = go.name;
        var t = go.transform.parent;
        while(t!=null){path = t.name+"/"+path; t=t.parent;}
        var ps = go.GetComponent<ParticleSystemRenderer>();
        string matName = (ps!=null && ps.sharedMaterial!=null) ? ps.sharedMaterial.name : "NO MAT";
        Debug.Log(go.name+" | path: "+path+" | pos: "+go.transform.position+" | mat: "+matName);
    }
}
var wc = GameObject.FindObjectOfType<WaterController>();
if(wc!=null && wc.waterParticles!=null){
    string path2=wc.waterParticles.gameObject.name;
    var t2=wc.waterParticles.transform.parent;
    while(t2!=null){path2=t2.name+"/"+path2;t2=t2.parent;}
    Debug.Log("WC.waterParticles PATH: "+path2+" pos: "+wc.waterParticles.transform.position);
}
